\caption{Paper overview. (a)~LLM classifiers exhibit heterogeneous error rates across subgroups (up to $5\times$). (b)~Global confusion-matrix correction over/under-corrects subgroups, introducing bias $\delta_s \cdot \Delta\tau / (1{-}2\bar{\pi})$ that can reverse CATE sign (14.9\% of configurations). (c)~EC-HTE corrects per-subgroup via hierarchical Bayes with a $\kappa$-guard. (d)~Key results across eight LLMs and 4 NLP tasks.}
\label{fig:overview}
\end{figure*}

\begin{figure*}[t]
\centering
